/**
 * Export a mapping artifact as deterministic JSON.
 * @summary Export Mapping
 */
export const getExportMappingUrl = (
  projectId: string,
  params: ExportMappingParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/projects/${projectId}/export?${stringifiedParams}`
    : `/projects/${projectId}/export`;
};

export const exportMapping = async (
  projectId: string,
  params: ExportMappingParams,
  options?: RequestInit,
): Promise<ExportResponse> => {
  return customFetch<ExportResponse>(getExportMappingUrl(projectId, params), {
    ...options,
    method: "POST",
  });
};

