/**
 * @summary List Catalog Schemas
 */
export const getListCatalogSchemasUrl = (params?: ListCatalogSchemasParams) => {
  const searchParams = new URLSearchParams();
  if (params?.type != null) searchParams.set("type", params.type);
  if (params?.format != null) searchParams.set("format", params.format);
  if (params?.status != null) searchParams.set("status", params.status);
  if (params?.q != null) searchParams.set("q", params.q);
  const qs = searchParams.toString();
  return `/catalog/schemas${qs ? `?${qs}` : ""}`;
};

export const listCatalogSchemas = async (
  params?: ListCatalogSchemasParams,
  options?: RequestInit,
): Promise<CatalogSchemaResponse[]> => {
  return customFetch<CatalogSchemaResponse[]>(getListCatalogSchemasUrl(params), {
    ...options,
    method: "GET",
  });
};

